package com.collaborativecanvas.client.service;
import com.collaborativecanvas.shared.dto.*;import com.collaborativecanvas.shared.enums.*;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class CanvasSyncServiceTest {private DrawingOperationMessage op(long n,String id){return new DrawingOperationMessage(UUID.randomUUID(),"ABCDEFGH","p",DrawingOperationType.DRAW_START,id,.2,.3,"#000000",4,false,n,null,null);}@Test void buffersOutOfOrderOperations(){var s=new CanvasSyncService(v->{});assertTrue(s.state(new CanvasStateMessage("ABCDEFGH","p",ServerEventType.CANVAS_STATE,1,0,0,CanvasDocument.empty(),List.of())));s.receive(op(2,"a"));assertEquals(0,s.lastApplied());s.receive(op(1,"a"));assertEquals(2,s.lastApplied());assertEquals(1,s.document().strokes().size());}
 @Test void refusesToMarkGappedInitialStateReady(){var gap=new java.util.concurrent.atomic.AtomicBoolean();var s=new CanvasSyncService(v->gap.set(true));assertFalse(s.state(new CanvasStateMessage("ABCDEFGH","p",ServerEventType.CANVAS_STATE,1,0,2,CanvasDocument.empty(),List.of(op(2,"a")))));assertTrue(gap.get());assertEquals(0,s.lastApplied());}}
